<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 维保卡生成</div><h1>{{isMaterial?'附带资料管理':'联系人管理'}}</h1><p>{{isMaterial?'上传已完成统一水印的 PDF，按原件预览和打印。':'维护负责人和联系电话，在生成维保卡时直接选用。'}}</p></div><el-button type="primary" icon="Plus" @click="edit()" v-hasPermi="[permission]">{{isMaterial?'上传资料':'添加联系人'}}</el-button></header><section class="zj-card"><div class="zj-filters"><el-input v-model="query.name" clearable :placeholder="isMaterial?'搜索资料名称':'搜索姓名或电话'" @keyup.enter="search"/><el-button type="primary" @click="search">查询</el-button><el-button @click="query.name='';search()">清空</el-button><el-button @click="load">刷新</el-button></div><el-alert v-if="error" title="加载失败，请刷新重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" :empty-text="isMaterial?'暂无附带资料，请上传完成水印的成品PDF':'暂无联系人'"><el-table-column prop="name" :label="isMaterial?'资料名称':'姓名'" min-width="220"/><el-table-column v-if="!isMaterial" prop="phone" label="联系电话" min-width="180"/><el-table-column v-if="isMaterial" prop="remark" label="备注" min-width="220"/><el-table-column label="操作" width="240"><template #default="{row}"><el-button v-if="isMaterial" link type="primary" @click="show(row)">预览 / 打印</el-button><el-button link type="primary" @click="edit(row)" v-hasPermi="[permission]">编辑</el-button><el-button link type="danger" @click="remove(row)" v-hasPermi="[permission]">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></section><el-drawer v-model="open" :title="form.id?'编辑':'新增'" size="min(600px,96vw)" :before-close="close" :close-on-click-modal="false"><el-form ref="refForm" :model="form" :rules="rules" label-position="top" :disabled="saving"><el-form-item :label="isMaterial?'资料名称':'姓名'" prop="name"><el-input v-model="form.name" :maxlength="isMaterial?200:100"/></el-form-item><template v-if="isMaterial"><el-alert title="只接受未加密PDF，最多50MB、300页。请先在系统外完成统一水印；系统不修改PDF内容。" type="info" :closable="false"/><el-form-item label="PDF文件" prop="file"><FileUpload v-model="form.file" :limit="1" :file-type="['pdf']" :file-size="50"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="2000"/></el-form-item></template><el-form-item v-else label="联系电话" prop="phone"><el-input v-model="form.phone" maxlength="50"/></el-form-item></el-form><template #footer><el-button @click="close(()=>open=false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer><PdfPreview v-model="preview" :url="pdfUrl" :title="pdfTitle"/></main></template>
<script setup>
import {onBeforeRouteLeave} from 'vue-router';
import {resourceList,saveResource,removeResource} from '@/api/wbcardWorkspace';import {fileUrl} from '@/utils/files';import FileUpload from '@/components/FileUpload/index.vue';import PdfPreview from './PdfPreview.vue';import '@/assets/styles/zhongji.scss';
const props=defineProps({kind:String});const isMaterial=computed(()=>props.kind==='materials'),permission=computed(()=>`management:wbcard:${props.kind}:edit`);const {proxy}=getCurrentInstance();const query=reactive({name:'',pageNum:1,pageSize:20}),rows=ref([]),total=ref(0),loading=ref(false),error=ref(false),open=ref(false),saving=ref(false),form=ref({}),refForm=ref(),preview=ref(false),pdfUrl=ref(''),pdfTitle=ref('');let snapshot='',sequence=0;
const rules={name:[{required:true,message:'请填写名称',trigger:'blur'}],phone:[{required:true,message:'请填写联系电话',trigger:'blur'}],file:[{required:true,message:'请上传PDF',trigger:'change'}]};
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await resourceList(props.kind,{...query});if(n===sequence){rows.value=r.rows;total.value=r.total}}catch{if(n===sequence){rows.value=[];total.value=0;error.value=true}}finally{if(n===sequence)loading.value=false}}
function search(){query.pageNum=1;load()}function edit(row){form.value=row?{...row}:{name:'',file:'',phone:'',remark:''};snapshot=JSON.stringify(form.value);open.value=true}
async function close(done){if(saving.value)return;if(snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('放弃未保存的内容？')}catch{return}}done()}
async function save(){if(saving.value)return;if(!await refForm.value.validate().catch(()=>false))return;saving.value=true;try{await saveResource(props.kind,{...form.value});open.value=false;proxy.$modal.msgSuccess('保存成功');await load()}finally{saving.value=false}}
async function remove(row){await proxy.$modal.confirm(`确认删除“${row.name}”？${isMaterial?'上传原件保留，不影响历史维保卡。':'已生成维保卡内容不受影响。'}`);await removeResource(props.kind,row.id);await load()}
function show(row){pdfUrl.value=fileUrl(row.file);pdfTitle.value=row.name;preview.value=true}onMounted(load);
onBeforeRouteLeave(async()=>{if(open.value&&snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('离开并放弃未保存的内容？')}catch{return false}}return true});
</script>
